const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Madre de Dios region, Peru
  const madreDeDios = ee.Geometry.Rectangle([-73.2, -13.0, -68.0, -11.5]);

  // Load Hansen Global Forest Change dataset
  const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_10');

  // Extract tree cover for 2013 and 2018
  const treeCover2013 = hansen.select('treecover2000'); // Baseline year 2000
  const lossYear = hansen.select('loss_year'); // Year of loss (1-23 = 2001-2023)

  // For 2013: pixels with no loss by 2013 have treecover2000, others reduced by annual loss
  // For 2018: pixels with loss_year <= 18 (by 2018) have lost trees

  // Create masks: 1 if forest exists, 0 if lost
  const forestMask2013 = treeCover2013.gt(10).and(
    lossYear.eq(0).or(lossYear.gt(13)) // No loss OR loss after 2013
  );

  const forestMask2018 = treeCover2013.gt(10).and(
    lossYear.eq(0).or(lossYear.gt(18)) // No loss OR loss after 2018
  );

  // Calculate mean tree cover for each year in the region
  const cover2013 = treeCover2013.updateMask(treeCover2013.gt(10))
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: madreDeDios,
      scale: 30,
      maxPixels: 1e9
    }).get('treecover2000');

  const cover2013Info = await ee.data.computeValue(cover2013);

  // Count valid forest pixels for 2013
  const pixelCount2013 = treeCover2013.updateMask(treeCover2013.gt(10))
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: madreDeDios,
      scale: 30,
      maxPixels: 1e9
    }).get('treecover2000');

  const pixelCount2013Info = await ee.data.computeValue(pixelCount2013);

  // Calculate forest cover loss 2013-2018
  const lossArea = hansen.select('loss').updateMask(
    lossYear.gte(14).and(lossYear.lte(18))
  );

  const lossPixels = lossArea.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: madreDeDios,
    scale: 30,
    maxPixels: 1e9
  }).get('loss');

  const lossPixelsInfo = await ee.data.computeValue(lossPixels);

  // Get total forest pixels in 2013 with valid coverage
  const totalForestPixels2013 = await ee.data.computeValue(pixelCount2013Info);
  const avgCover2013 = await ee.data.computeValue(cover2013Info);

  print(`2013 Forest: Avg Cover=${avgCover2013?.toFixed(1) || 'N/A'}%, Valid Pixels=${totalForestPixels2013 || 0}`);
  print(`2013-2018 Loss: ${lossPixelsInfo || 0} pixels lost`);

  // Validation checks
  if (totalForestPixels2013 === null || totalForestPixels2013 === 0) {
    print("No valid forest pixels in 2013.");
    print("C2");
    return;
  }

  if (avgCover2013 === null || isNaN(avgCover2013) || avgCover2013 < 0 || avgCover2013 > 100) {
    print("Invalid tree cover value.");
    print("C3");
    return;
  }

  if (lossPixelsInfo === null || lossPixelsInfo === 0) {
    print("No forest loss detected 2013-2018.");
    print("B");
    return;
  }

  // Forest loss occurred = decrease in forest cover
  print(`Forest loss occurred: ${lossPixelsInfo} pixels (${((lossPixelsInfo/totalForestPixels2013)*100).toFixed(2)}% of 2013 forest)`);
  print("A");
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
